window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f7683b2b1560f3c1"]={"versions": [{"id": "FIG-f7683b2b1560f3c1", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Feature-Baum / Feature-Modelldiagramm (Variabilitäts- und Dekompositionsmodellierung nach FODA-/Czarnecki-Notation im Rahmen der AUTOSAR Foundation). Kein UML-Klassendiagramm, kein Verhaltensmodell.\n</li><li><strong>Technischer Zweck:</strong> Spezifikation von High-Level-Systemmerkmalen und deren Dekompositionsbeziehungen im Dokument <code>AUTOSAR_FO_TR_Features</code>. Es modelliert das plattformübergreifende Strukturmerkmal <code>FO_TR_FEAT_00078</code> (<em>Software_Clustering</em>) und definiert dessen optionale Sub-Feature-Hierarchie.\n</li><li><strong>Architektur-Kontext:</strong> Dient der formalen Strukturierung der Plattform-Fähigkeiten (insb. Classic Platform ab R20-11/R21-11 und fortgeführt in R24-11). Software Clustering ermöglicht die logische und funktionale Partitionierung der ECU-Software in separat compilierbare, linkbare, testbare und flashbare Einheiten (Software Cluster).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten (Feature-Knoten):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00078</code> (<code>Software_Clustering</code>): Parent-Feature / Root-Feature. Definiert die grundlegende Plattformfähigkeit, Software auf einer ECU in eigenständige Software-Cluster (Host-Cluster, Application-Cluster) aufzuteilen.\n</li><li><code>FO_TR_FEAT_00237</code> (<code>Modular_Software_Cluster_Support</code>): Child-Feature / Sub-Feature. Spezifiziert die modulare Erweiterbarkeit und Unabhängigkeit von Software-Clustern.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Semantik:</strong>\n<ul class=\"fig-list\"><li><strong>Kantenart:</strong> Gerichtete Zerlegungskante mit <strong>ungefülltem Kreis (Hohlkreis <code>○</code>)</strong> am Ansatzpunkt des Sub-Knotens.\n</li><li><strong>Kardinalität / Variabilität:</strong> <strong>Optionales Feature</strong> (Kardinalität <code>0..1</code>).\n</li><li><strong>Ableitungslogik:</strong> Eine Plattformimplementierung, die <code>FO_TR_FEAT_00078</code> unterstützt, kann <code>FO_TR_FEAT_00237</code> optional einbinden. Es besteht keine zwingende Implementierungsverpflichtung für Modularität, wenn lediglich monolithisches Software-Clustering realisiert wird.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li><strong>Laufzeit-Dynamik:</strong> Nicht zutreffend, da es sich um ein rein statisches Dekompositions- und Variabilitätsmodell auf Anforderungsebene handelt. Es existieren keine synchronen/asynchronen Runtime-Pfade, Callbacks oder Zustandsübergänge im Diagramm.\n</li><li><strong>Lifecycle-Relevanz (Entwurfs-, Build- und Integrationsphase):</strong>\n<ul class=\"fig-list\"><li><em>Design-/Konfigurationszeit:</em> Auswahl des Features <code>FO_TR_FEAT_00237</code> aktiviert im AUTOSAR-Metamodell die Entkopplungsstrukturen für modulare Cluster-Schnittstellen (<code>SoftwareCluster</code>, <code>SoftwareClusterDesign</code>).\n</li><li><em>Build-/Integrationszeit:</em> Bestimmt, ob Build-Artefakte als monolithisches Gesamt-Binary oder als separat linkbare Binaries mit fixierten Symboltabellen (Inter-Cluster-Interfaces) erzeugt werden.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Auswirkungen auf BSW- und OS-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Bei Aktivierung von <code>FO_TR_FEAT_00237</code> müssen OS und Basissoftware (BSW) Mechanismen bereitstellen, um Software-Cluster modular und unabhängig voneinander zu behandeln (u. a. separate MPU-Regionen, isolierte Task-Gruppen, entkoppeltes Scheduling und Memory-Protection).\n</li><li>Notwendigkeit von Inter-Software-Cluster-Kommunikationsstrukturen (ISCC) und fixierten Sprungtabellen / Inter-Cluster Call Tables (ICCT), damit Adressverschiebungen eines modularen Clusters keine Re-Kompilierung der übrigen Cluster erzwingen.\n</li></ul>\n</li><li><strong>Auswirkungen auf RTE- und Stack-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Die RTE muss cluster-lokale RTE-Anteile unterstützen, die mit einer Host-RTE interagieren, anstatt eine globale, monolithisch generierte RTE vorauszusetzen.\n</li><li>Modulare Cluster erfordern strikt typisierte Cross-Cluster-Interfaces; direkte C-Funktionsaufrufe über Clustergrenzen hinweg sind untersagt.\n</li></ul>\n</li><li><strong>Einschränkungen für Applikations-Entwickler (SWC-Ebene):</strong>\n<ul class=\"fig-list\"><li>SWCs innerhalb eines modularen Clusters dürfen keine harten Symbolabhängigkeiten zu Modulen außerhalb des eigenen Clusters besitzen. Der Export und Import von Datentypen und Schnittstellen muss strikt über ARXML-Schnittstellenbeschreibungen harmonisiert sein.\n</li></ul>\n</li></ul>"}, {"id": "FIG-85f43d1c860f8d79", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Feature-Baum / Feature-Modelldiagramm (Variabilitäts- und Dekompositionsmodellierung nach FODA-/Czarnecki-Notation im Rahmen der AUTOSAR Foundation). Kein UML-Klassendiagramm, kein Verhaltensmodell.\n</li><li><strong>Technischer Zweck:</strong> Spezifikation von High-Level-Systemmerkmalen und deren Dekompositionsbeziehungen im Dokument <code>AUTOSAR_FO_TR_Features</code>. Es modelliert das plattformübergreifende Strukturmerkmal <code>FO_TR_FEAT_00078</code> (<em>Software_Clustering</em>) und definiert dessen optionale Sub-Feature-Hierarchie.\n</li><li><strong>Architektur-Kontext:</strong> Dient der formalen Strukturierung der Plattform-Fähigkeiten (insb. Classic Platform ab R20-11/R21-11 und fortgeführt in R24-11). Software Clustering ermöglicht die logische und funktionale Partitionierung der ECU-Software in separat compilierbare, linkbare, testbare und flashbare Einheiten (Software Cluster).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten (Feature-Knoten):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00078</code> (<code>Software_Clustering</code>): Parent-Feature / Root-Feature. Definiert die grundlegende Plattformfähigkeit, Software auf einer ECU in eigenständige Software-Cluster (Host-Cluster, Application-Cluster) aufzuteilen.\n</li><li><code>FO_TR_FEAT_00237</code> (<code>Modular_Software_Cluster_Support</code>): Child-Feature / Sub-Feature. Spezifiziert die modulare Erweiterbarkeit und Unabhängigkeit von Software-Clustern.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Semantik:</strong>\n<ul class=\"fig-list\"><li><strong>Kantenart:</strong> Gerichtete Zerlegungskante mit <strong>ungefülltem Kreis (Hohlkreis <code>○</code>)</strong> am Ansatzpunkt des Sub-Knotens.\n</li><li><strong>Kardinalität / Variabilität:</strong> <strong>Optionales Feature</strong> (Kardinalität <code>0..1</code>).\n</li><li><strong>Ableitungslogik:</strong> Eine Plattformimplementierung, die <code>FO_TR_FEAT_00078</code> unterstützt, kann <code>FO_TR_FEAT_00237</code> optional einbinden. Es besteht keine zwingende Implementierungsverpflichtung für Modularität, wenn lediglich monolithisches Software-Clustering realisiert wird.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Laufzeit-Dynamik:</strong> Nicht zutreffend, da es sich um ein rein statisches Dekompositions- und Variabilitätsmodell auf Anforderungsebene handelt. Es existieren keine synchronen/asynchronen Runtime-Pfade, Callbacks oder Zustandsübergänge im Diagramm.\n</li><li><strong>Lifecycle-Relevanz (Entwurfs-, Build- und Integrationsphase):</strong>\n<ul class=\"fig-list\"><li><em>Design-/Konfigurationszeit:</em> Auswahl des Features <code>FO_TR_FEAT_00237</code> aktiviert im AUTOSAR-Metamodell die Entkopplungsstrukturen für modulare Cluster-Schnittstellen (<code>SoftwareCluster</code>, <code>SoftwareClusterDesign</code>).\n</li><li><em>Build-/Integrationszeit:</em> Bestimmt, ob Build-Artefakte als monolithisches Gesamt-Binary oder als separat linkbare Binaries mit fixierten Symboltabellen (Inter-Cluster-Interfaces) erzeugt werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Auswirkungen auf BSW- und OS-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Bei Aktivierung von <code>FO_TR_FEAT_00237</code> müssen OS und Basissoftware (BSW) Mechanismen bereitstellen, um Software-Cluster modular und unabhängig voneinander zu behandeln (u. a. separate MPU-Regionen, isolierte Task-Gruppen, entkoppeltes Scheduling und Memory-Protection).\n</li><li>Notwendigkeit von Inter-Software-Cluster-Kommunikationsstrukturen (ISCC) und fixierten Sprungtabellen / Inter-Cluster Call Tables (ICCT), damit Adressverschiebungen eines modularen Clusters keine Re-Kompilierung der übrigen Cluster erzwingen.\n</li></ul>\n</li><li><strong>Auswirkungen auf RTE- und Stack-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Die RTE muss cluster-lokale RTE-Anteile unterstützen, die mit einer Host-RTE interagieren, anstatt eine globale, monolithisch generierte RTE vorauszusetzen.\n</li><li>Modulare Cluster erfordern strikt typisierte Cross-Cluster-Interfaces; direkte C-Funktionsaufrufe über Clustergrenzen hinweg sind untersagt.\n</li></ul>\n</li><li><strong>Einschränkungen für Applikations-Entwickler (SWC-Ebene):</strong>\n<ul class=\"fig-list\"><li>SWCs innerhalb eines modularen Clusters dürfen keine harten Symbolabhängigkeiten zu Modulen außerhalb des eigenen Clusters besitzen. Der Export und Import von Datentypen und Schnittstellen muss strikt über ARXML-Schnittstellenbeschreibungen harmonisiert sein.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-f7683b2b1560f3c1", "to": "FIG-85f43d1c860f8d79", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
